#pragma once
static void checkDetailedDrawingSettings(App& app,const std::string& dir){
 auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(std::string("detailed drawing: ")+why);};
 DrawingSettings c;c.path=W(dir+"/detailed.ini");c.acsDefaults();require(c.boldWidth==2&&c.marginWidth==1.6&&c.hashSpacing==2.5&&c.bondSpacing==18&&c.chainAngle==120,"complete ACS values");
 DrawingSettings legacy;legacy.path=W(dir+"/legacy-drawing.ini");require(DrawingSettings::write(legacy.path,L"[Drawing]\r\nPreset=RSC (1 Column)\r\nBondLength=12.2\r\nLineWidth=0.5\r\nFont=Arial\r\nFontSize=7\r\n"),"write legacy preferences");legacy.load();require(legacy.boldWidth==1.6&&legacy.bondSpacing==20&&legacy.hashSpacing==1.8,"legacy settings gain selected preset details");
 for(const auto& style:journalStyles()){c.use(style);require(c.valid(),"all audited presets valid");}require(journalStyles().size()==14,"all original preset choices retained");
 c.acsDefaults();c.bondLength=19;c.lineWidth=.85;c.boldWidth=3.2;c.marginWidth=2.3;c.hashSpacing=3.5;c.bondSpacing=24;c.chainAngle=110;c.fontName=L"Arial";c.fontSize=9;c.captionFontName=L"Times New Roman";c.captionFontSize=13;c.preset=L"测试样式 α";require(c.save(),"save independent custom values");DrawingSettings loaded;loaded.path=c.path;loaded.load();require(loaded.boldWidth==3.2&&loaded.marginWidth==2.3&&loaded.hashSpacing==3.5&&loaded.bondSpacing==24&&loaded.chainAngle==110&&loaded.fontSize==9&&loaded.captionFontSize==13&&loaded.captionFontName==L"Times New Roman","restart retains all detailed values");
 require(c.saveTemplates({c}),"store custom template");auto rows=c.templates();require(rows.size()==1&&rows[0].preset==c.preset&&rows[0].captionFontSize==13&&rows[0].hashSpacing==3.5,"custom template round trip");require(c.saveTemplates({})&&c.templates().empty(),"delete custom template");auto bad=c;bad.hashSpacing=0;require(!bad.save()&&c.templates().empty(),"invalid values cannot be saved");
 Session s;c.apply(s.doc);ObjectId a,b,bond;s.doc.addAtom(Vec2(100,100),7,&a);s.doc.addAtom(Vec2(119,100),8,&b);s.doc.addBond(a,b,&bond);auto sem=s.doc.atoms().alive(a)->semantics;sem.implicitHydrogens=0;s.doc.setAtomSemantics(a,sem);sem=s.doc.atoms().alive(b)->semantics;sem.implicitHydrogens=0;s.doc.setAtomSemantics(b,sem);s.doc.setBondOrder(bond,BondOrder::Double);ObjectId caption;s.doc.addText(Vec2(100,140),s.doc.defaultTextSize(),"caption",&caption);require(s.doc.runs(caption).front().fontName=="Times New Roman","new caption inherits independent caption font");s.refresh();require(s.save(dir+"/detailed-drawing.cdxml",true).ok(),"export settings");
 tinyxml2::XMLDocument xml;{std::ifstream in(dir+"/detailed-drawing.cdxml");std::string bytes((std::istreambuf_iterator<char>(in)),{});require(xml.Parse(bytes.c_str())==tinyxml2::XML_SUCCESS,"parse exported settings");}auto root=xml.RootElement();for(auto p:std::vector<std::pair<const char*,double>>{{"BondLength",19},{"LineWidth",.85},{"BoldWidth",3.2},{"MarginWidth",2.3},{"HashSpacing",3.5},{"BondSpacing",24},{"ChainAngle",110},{"LabelSize",9},{"CaptionSize",13}})require(std::abs(root->DoubleAttribute(p.first)-p.second)<1e-6,"each CDXML setting retained");
 Session re;require(re.open(dir+"/detailed-drawing.cdxml").ok(),"reopen detailed styles");require(re.doc.defaultFont()=="Times New Roman"&&*re.doc.documentExtensions().findValue("studio.style.LabelFontName")=="Arial","separate atom and caption fonts survive");
 rings_chains::PlacementPolicy policy;policy.chainAtomCount=3;policy.fixedAngles=true;auto request=rings_chains::chainRequestFor(s.doc,Vec2(),Vec2(80,0),policy);request.options.snaking=true;rings_chains::ChainPlan plan;require(rings_chains::resolveChainPlan(s.doc,request,&plan).ok()&&plan.atoms.size()>=2,"chain resolves with configured angle");auto u=plan.origin-plan.atoms[0].position,v=plan.atoms[1].position-plan.atoms[0].position;double angle=std::acos(std::max(-1.,std::min(1.,dot(u,v)/(length(u)*length(v)))))*180/3.141592653589793;require(std::abs(angle-110)<1e-6,"chain geometry uses configured interior angle");
 auto env=rings_chains::buildSproutEnvironment(s.doc,a,25);auto sprout=rings_chains::resolveSproutDirection(env,0);require(sprout.ok&&std::abs(std::abs(sprout.directionDeg)-110)<1e-6,"new bond sprouting uses configured chain angle");
 std::string binary,decoded,error;require(cdxbinary::fromXml(std::string("<CDXML ChainAngle='110'><page id='1'/></CDXML>"),binary,error)&&cdxbinary::toXml(binary,decoded,error),"CDX chain angle codec");require(binary.find(std::string("\x03\x08\x04\x00\x00\x00\x6e\x00",8))!=std::string::npos,"CDX angle uses documented 16.16 representation");tinyxml2::XMLDocument cdx;require(cdx.Parse(decoded.c_str())==tinyxml2::XML_SUCCESS&&std::abs(cdx.RootElement()->DoubleAttribute("ChainAngle")-110)<1e-6,"CDX fixed point chain angle round trip");
 std::ofstream(dir+"/detailed-drawing-checks.json")<<"{\"presets\":14,\"independent_fields\":true,\"ini_restart\":true,\"custom_templates\":true,\"validation\":true,\"cdxml_styles\":true,\"separate_fonts\":true,\"chain_geometry\":true,\"sprout_geometry\":true,\"cdx_chain_angle\":true}";
 (void)app;
}
